///  <span class="type"><a href="http://doc.qt.io/qt-5/qlistview.html" translate="no">QListView</a></span> <span class="operator">*</span>listview <span class="operator">=</span> <span class="keyword">new</span> <span class="type"><a href="http://doc.qt.io/qt-5/qlistview.html" translate="no">QListView</a></span>;
///  <span class="type"><a href="http://doc.qt.io/qt-5/qtreeview.html" translate="no">QTreeView</a></span> <span class="operator">*</span>treeview <span class="operator">=</span> <span class="keyword">new</span> <span class="type"><a href="http://doc.qt.io/qt-5/qtreeview.html" translate="no">QTreeView</a></span>;
